text(ct.setup,'Minimum budget check','',14,V('setup/budget-note','STRING',L('Сначала выберите трейдера','Choose a trader first')));const launchButton=ct['setup-review'].findOne(n=>n.name==='Action / '+L('Запустить демо','Start demo'));if(launchButton)await react(launchButton,[cond(eq(configureAllowed,true),[set(V('has-draft','BOOLEAN',false),false),nav(fs.launch.id)],[nav(fs.setup.id)])]);
// Every detail entry path sets action eligibility from the selected ID, including related records.
function eligibility(actions){const out=[];for(const a of actions){if(a.type==='CONDITIONAL')out.push({...a,conditionalBlocks:a.conditionalBlocks.map(b=>({...b,actions:eligibility(b.actions)}))});else{if(a.type==='NODE'&&a.destinationId===fs['detail-order'].id){const sid=actions.find(x=>x.type==='SET_VARIABLE'&&x.variableId===E('order/id').id)?.variableValue?.value;const o=DATA.orders.find(o=>o.id===sid);if(o)out.push(set(V('order/can-cancel','BOOLEAN',false),['open','partial'].includes(o.status)&&o.remainingQuantity>0),set(V('order/remainder','STRING',''),L('Осталось долей: ','Remaining shares: ')+o.remainingQuantity+' · '+L('Резерв: ','Reserved: ')+money(o.reservedCents)));}if(a.type==='NODE'&&a.destinationId===fs['detail-position'].id){const sid=actions.find(x=>x.type==='SET_VARIABLE'&&x.variableId===E('position/id').id)?.variableValue?.value;const o=DATA.positions.find(o=>o.id===sid);if(o)out.push(set(V('position/can-close','BOOLEAN',false),['open','manual'].includes(o.status)&&o.quantity>0),set(V('position/can-manual','BOOLEAN',false),o.status==='open'&&o.management!=='manual'));}out.push(a);}}return out;}
for(const n of section.findAll(x=>'reactions'in x&&x.reactions.length)){const next=n.reactions.map(r=>({...r,actions:eligibility(r.actions||[])}));if(JSON.stringify(next)!==JSON.stringify(n.reactions)){await n.setReactionsAsync(next);changed.add(n.id);}}
