const olds=page.findAllWithCriteria({types:['FRAME']}).filter(f=>f.parent.type==='SECTION'&&f.parent!==section&&!f.name.startsWith('Reference'));
const map=new Map();for(const f of olds){const key=(f.name.match(/^(D\d+[a-z]?|M\d+)\s/)||[])[1]||'';let target=null;
if(/^D03$/.test(key))target='catalog';if(/^D05/.test(key))target=key==='D05a'?'trader-7d':key==='D05b'?'trader-90d':key==='D05c'?'trader-24h':'trader-30d';if(/^D07$|^M04$/.test(key))target='setup';if(/^D11$|^M07$/.test(key))target='setup-review';if(/^D12$/.test(key)||/U12.*Starting/.test(f.name))target='launch';if(/^D13$|^D16$/.test(key)||/U13.*paper session/i.test(f.name))target='home';if(/^D17$/.test(key))target='positions';if(/^D19$/.test(key))target='events';if(/^D25$|^M16$/.test(key))target='profile';if(/^D14$/.test(key))target='fresh-funds';if(target){map.set(f.id,fs[target].id);f.name='Reference · replaced route / '+f.name;changed.add(f.id);}}
function rewrite(as){return as.map(a=>a.type==='CONDITIONAL'?{...a,conditionalBlocks:a.conditionalBlocks.map(b=>({...b,actions:rewrite(b.actions)}))}:a.type==='NODE'&&map.has(a.destinationId)?{...a,destinationId:map.get(a.destinationId)}:a);}
for(const n of page.findAll(x=>'reactions'in x&&x.reactions.length)){const as=n.reactions[0].actions||[];const next=rewrite(as);if(JSON.stringify(as)!==JSON.stringify(next))await react(n,next);}
for(const f of section.children.filter(n=>n.type==='FRAME')){const left=f.findOne(n=>n.name==='Workspace navigation');if(left)for(const n of left.children){if(n.name==='Action / '+L('Главная','Home'))await react(n,home);if(n.name==='Action / '+L('Трейдеры','Traders'))await react(n,[nav(fs.catalog.id)]);if(n.name==='Action / '+L('Позиции','Positions'))await react(n,[cond(eq(stage,'active'),[nav(fs.positions.id)],[nav(fs['fresh-positions'].id)])]);if(n.name==='Action / '+L('События','Events'))await react(n,[cond(eq(stage,'active'),[nav(fs.events.id)],[nav(fs['fresh-events'].id)])]);if(n.name==='Action / '+L('Помощь','Help'))await react(n,[nav(fs.help.id)]);}
for(const n of f.findAll(x=>'reactions'in x)){if(n.name==='Button/Balance → Wallets')await react(n,[cond(eq(stage,'active'),[nav(fs.funds.id)],[nav(fs['fresh-funds'].id)])]);if(n.name==='Button/Profile avatar')await react(n,[nav(fs.profile.id)]);}
}
// Keep all-period source coverage honest; make specialization and missing last trade explicit.
for(const t of DATA.traders){const coverage=V('trader/coverage','STRING',''),special=V('trader/specialization','STRING','');for(const n of section.findAllWithCriteria({types:['INSTANCE']})){if(n.name==='Item / trader / '+t.id&&n.reactions[0]?.actions)await react(n,[set(coverage,L('Доступная история: ','Available history: ')+t.historyDays+L(' дней · полный PnL за этот срок не рассчитан',' days · full-coverage PnL is unavailable')),set(special,L('Тестовая тема: ','Test theme: ')+[L('Политика','Politics'),L('Спорт','Sports'),L('Крипто','Crypto')][(Number(t.id.split('-')[1])-1)%3])].concat(n.reactions[0].actions));}}
text(ct['trader-all'],'Coverage start','',14,V('trader/coverage','STRING',''));for(const k of ['trader-24h','trader-7d','trader-30d','trader-90d']){const c=card(ct[k],L('Тема и последняя публичная сделка','Theme and last public trade'),L('Последняя публичная сделка: нет данных в тестовом наборе. Личные копирования не подменяют общую торговлю трейдера.','Last public trade: unavailable in the test fixture. Personal copies do not replace the trader’s public history.'));text(c,'Theme','',14,V('trader/specialization','STRING',''));const sim=findOld(desk?/^D06/:/U06/);if(sim)await button(ct[k],L('Историческая симуляция · пример','Historical simulation · example'),[cond(eq(E('trader/id'),'trader-01'),[nav(sim.id)],[nav(findOld(/trader-data-unavailable/)?.id||fs['trader-all'].id)])]);}
